#!/bin/bash
# ep02 painted plates via Codex built-in image generation (ChatGPT plan). Prompts = money-mirage/episodes/ep02/art_prompts.md (approved).
# Usage: ./gen.sh [name ...]   (no args = all, in order). Resumable: skips existing PNGs.
OUT=/home/claude/mm-work/ep02/plates; mkdir -p "$OUT"; cd "$OUT"
STYLE="Cinematic painterly illustration for a dark, mysterious history documentary: rich oil-painting texture, chiaroscuro lighting with warm amber-gold highlights against deep navy-blue shadows, muted desaturated palette, light haze, shallow depth of field, composed like a film still with the main subject slightly off-centre and calm darker space in the lower third for captions. No text, no letters, no numbers, no writing, no logos, no watermarks, no signatures, no borders. No recognizable real people; any people are anonymous, seen from behind, in silhouette or partly in shadow. Landscape 1536x1024, opaque PNG."
declare -A J
ORDER=(boe_dawn dealing_room_1992 phones_offhook treasury_courtyard ny_tower_night ny_office_window euro_notes_pile canal_buoys bundesbank_frankfurt strict_friend berlin_wall_night east_cranes presses_marks uk_high_street_1991 repossessed_house medicine_bottle coin_spin vault_full vault_empty basel_tower rome_lira presses_newspaper wire_terminal chess_queen red_phone note_falling bathtub election_night_1997 target_board brass_key)
J[boe_dawn]="The columned, windowless stone outer wall of the Bank of England in the City of London at dawn in September 1992, seen from street level at a low angle, empty wet pavement, first grey-blue daylight on the stone, a few black cabs as dark shapes with headlights on, mist between the buildings."
J[dealing_room_1992]="A 1992 central-bank foreign-exchange dealing room seen from the back of the room: rows of beige desks with bulky CRT monitors showing only abstract green glowing lines and blocks (nothing readable), many telephones, coiled phone cords, paper everywhere, dealers in white shirtsleeves seen from behind, one standing with a phone to his ear, a large plain analogue wall clock with a completely blank face and no numerals high on the far wall, cold fluorescent light mixed with warm desk lamps."
J[phones_offhook]="Close-up of a 1992 trading desk at the height of panic: a dozen beige desk telephones with several receivers off the hook and dangling by their cords, a full ashtray, scattered blank dealing slips, a cold cup of tea, CRT glow from the side, shallow depth of field."
J[treasury_courtyard]="A London government courtyard at night in 1992: tall grey Edwardian stone walls with lit windows, a cluster of television cameras on tripods and bright TV lights in the foreground seen from behind, press photographers in silhouette, a single anonymous man in a dark suit at a microphone stand far away and tiny, back-lit so he is only a dark shape, light drizzle glittering in the lamp beams."
J[ny_tower_night]="A Manhattan skyscraper at night in 1992 seen from below in the rain, almost every window dark except one high floor glowing warm amber, yellow cabs as streaks of light on the street below, steam rising from a manhole."
J[ny_office_window]="Inside a high Manhattan office at night in 1992: a lone anonymous figure in shirtsleeves standing at a floor-to-ceiling window with his back to us, looking out over the lit city, a desk behind him with a telephone, a CRT screen with abstract green lines and a stack of papers, the room dark except for the city glow and one desk lamp."
J[euro_notes_pile]="A messy heap of many different generic, unreadable European-style paper banknotes in different colours (pale green, violet, brown, blue) with ornate guilloche patterns but no words, no numbers and no faces, spread across a dark wooden desk with an old brass desk scale and a magnifying glass, warm lamp light."
J[canal_buoys]="A dark calm canal at night seen from a low angle: two long straight rows of glowing amber buoys mark a narrow channel stretching into the distance, and several small wooden rowing boats drift inside the channel between the buoy lines, one boat touching the lower row of buoys, mist on the water."
J[bundesbank_frankfurt]="A huge brutalist 1970s concrete central-bank office block on the edge of Frankfurt at dusk, long horizontal bands of windows, a few lit, flat grey sky turning navy, empty forecourt, bare trees, severe and powerful mood."
J[strict_friend]="Two anonymous young students at a dimly lit café table seen from the side and slightly behind: one sheepishly slides a plain blank bank card across the table, the other, stern and upright, takes it and slips it into a buttoned jacket pocket, warm lamp light, rain on the window."
J[berlin_wall_night]="Crowds of anonymous people standing on top of a long graffiti-covered concrete wall at night in 1989, seen from far away and below, silhouetted against floodlights and camera flashes, some with hammers raised, euphoric mood, smoke in the light."
J[east_cranes]="A grey East German city in 1991 at dusk: rows of worn prefabricated concrete apartment blocks, several tall construction cranes over half-built new buildings, a cracked road and a small Trabant-style car, a cold low sun breaking through."
J[presses_marks]="An industrial banknote printing hall at night: large printing presses running, long continuous sheets of generic unreadable green-blue banknote paper streaming through rollers, stacks of bundled blank notes on pallets, steam and warm machine light, no people."
J[uk_high_street_1991]="A British high street in 1991 on a rainy evening: shuttered shops, a boarded-up shop front, blank \"to let\" boards with no lettering, a red phone box, a lone figure with an umbrella walking away, wet reflections of orange streetlights."
J[repossessed_house]="A modest British brick terraced house at dusk with its windows boarded up, a blank estate agent's sign on a post in the tiny front garden, a family of three seen from behind in silhouette walking away down the pavement carrying cardboard boxes, drizzle."
J[medicine_bottle]="An old brown glass medicine bottle with a blank paper label and a spoon on a bedside table, the bottle nearly empty, beside it a small stack of plain paper pound-style banknotes with no design, lamp light, very shallow depth of field."
J[coin_spin]="A large old gold coin spinning on its edge on a dark green baize card table, motion blur on the coin, a single overhead lamp creating a pool of light, smoke curling, darkness all around. Blank coin faces with no design."
J[vault_full]="A modern 1990s central-bank reserve vault: tall steel shelves stacked high with gold bars and neatly bundled stacks of generic foreign banknotes (no designs visible), cold white strip lighting, a polished concrete floor, a heavy round vault door open in the foreground."
J[vault_empty]="EDIT of the attached image: keep everything identical (same camera, lighting, door, shelves) but the shelves are now almost completely bare, only a few scattered bundles left, empty pallets, one dangling light flickering."
J[basel_tower]="A tall cylindrical modernist office tower beside a railway station in Basel at night, warm lit windows, an old Swiss tram passing in the foreground, light fog, a few anonymous figures in coats with briefcases."
J[rome_lira]="A Roman piazza at night in 1992 with a grand palazzo lit up, a gust of wind blowing many loose generic unreadable pale banknotes across the wet cobblestones, a scooter parked by a fountain, one figure in silhouette holding a hat."
J[presses_newspaper]="A newspaper printing hall at night in 1992: giant rotary presses running at full speed, a blur of newsprint pages with only grey unreadable texture, a printer in overalls seen from behind, bright work lights and deep shadows."
J[wire_terminal]="A dark 1992 office with a single green-phosphor computer terminal glowing, the screen showing only abstract glowing lines (no readable characters), a ticking teleprinter beside it spilling a long ribbon of blank paper onto the floor, a cold cup of coffee."
J[chess_queen]="A close-up of a dark wooden chessboard under a single lamp: an anonymous hand moving the white queen forward in an aggressive attack, toppled black pieces around, deep shadows, tension."
J[red_phone]="A dim Georgian government office in London at dusk: a plain red telephone on a large mahogany desk, the receiver lifted and lying on its side, tall sash windows with rain streaking down, papers spread across the desk, a green banker's lamp glowing."
J[note_falling]="A single generic unreadable British-style banknote with no design falling slowly down a deep, dark, square stone stairwell, caught in a shaft of light from above, dust in the air, a dizzying view from above looking down."
J[bathtub]="A grand old-fashioned white clawfoot bathtub in a Georgian bathroom at night, steam rising, a small rubber duck on the rim, a radio on a stool, warm candle light, nobody in the room."
J[election_night_1997]="A huge crowd of anonymous people in silhouette celebrating outdoors at dawn, red balloons rising into a pale sky, confetti in the air, seen from behind and slightly above, joyful mood."
J[target_board]="An old wooden dartboard-style target on a dark wall with a plain ring pattern and no numbers, a single dart planted inside the middle ring, warm side light, shallow depth of field."
J[brass_key]="A single large ornate brass key lying on a polished mahogany table in a grand Georgian boardroom, tall windows with morning light, a long table with empty leather chairs, dust in the light."
LIST=("$@"); [ ${#LIST[@]} -eq 0 ] && LIST=("${ORDER[@]}")
for n in "${LIST[@]}"; do
  [ -f "$n.png" ] && { echo "skip $n"; continue; }
  t0=$(date +%s)
  if [ "$n" = vault_empty ]; then
    [ -f vault_full.png ] || { echo "vault_empty needs vault_full.png first"; continue; }
    timeout 420 codex exec --skip-git-repo-check -s workspace-write "Use your built-in image generation tool to EDIT the attached image and save the result in the current directory as $n.png. ${J[$n]} $STYLE Do not do anything else." -i vault_full.png < /dev/null > "log_$n.txt" 2>&1
  else
    timeout 420 codex exec --skip-git-repo-check -s workspace-write "Use your built-in image generation tool to create ONE image and save it in the current directory as $n.png. Image: ${J[$n]} $STYLE Do not do anything else." < /dev/null > "log_$n.txt" 2>&1
  fi
  echo "$n exit=$? $(( $(date +%s) - t0 ))s $( [ -f $n.png ] && echo OK || echo MISSING )"
done
echo ALLDONE
